+                @switch (_currentStep)
+                {
+                    case 1:
+                        <StepPersonalInfo State="_state"
+                                          EmailError="@_emailError"
+                                          OnNext="HandlePersonalInfoNext" />
+                        break;
+                    case 2:
+                        <StepWorkHistory State="_state"
+                                         OnBack="GoBack"
+                                         OnNext="GoNext" />
+                        break;
+                    case 3:
+                        <StepReferences State="_state"
+                                        OnBack="GoBack"
+                                        OnNext="GoNext" />
+                        break;
+                    case 4:
+                        <StepCoverLetter State="_state"
+                                         OnBack="GoBack"
+                                         OnNext="GoNext" />
+                        break;
+                    case 5:
+                        <StepReview State="_state"
+                                    OnBack="GoBack"
+                                    OnEditStep="GoToStep"
+                                    OnSubmit="HandleSubmit"
+                                    IsSubmitting="_isSubmitting"
+                                    SubmitError="@_submitError" />
+                        break;
+                }
+            </div>
+        </div>
+    }
+    else
+    {
+        <div class="card mt-4">
+            <div class="card-body text-center py-5">
+                <div class="text-success mb-3">
+                    <svg xmlns="http://www.w3.org/2000/svg" width="64" height="64" fill="currentColor" viewBox="0 0 16 16">
+                        <path d="M16 8A8 8 0 1 1 0 8a8 8 0 0 1 16 0m-3.97-3.03a.75.75 0 0 0-1.08.022L7.477 9.417 5.384 7.323a.75.75 0 0 0-1.06 1.06L6.97 11.03a.75.75 0 0 0 1.079-.02l3.992-4.99a.75.75 0 0 0-.01-1.05z"/>
+                    </svg>
+                </div>
+                <h2 class="text-success">Application Submitted!</h2>
+                <p class="lead mt-3">Your application has been received.</p>
+                <p class="fs-5">Application ID: <strong>#@_applicationId</strong></p>
+            </div>
+        </div>
+    }
+</div>
+
+@code {
+    private readonly ApplicationFormState _state = new();
+    private int _currentStep = 1;
+    private readonly HashSet<int> _completedSteps = new();
+    private bool _submitted;
+    private int _applicationId;
+    private bool _isSubmitting;
+    private string? _submitError;
+    private string? _emailError;
+
+    private async Task HandlePersonalInfoNext()
+    {
+        _emailError = null;
+
+        if (string.IsNullOrWhiteSpace(_state.FullName) ||
+            string.IsNullOrWhiteSpace(_state.Email) ||
+            string.IsNullOrWhiteSpace(_state.Phone) ||
+            string.IsNullOrWhiteSpace(_state.Address))
+        {
+            return;
+        }
+
+        var emailValid = await ApplicationService.ValidateEmailAsync(_state.Email);
+        if (!emailValid)
+        {
+            _emailError = "This email address is not valid. Please use a different email.";
+            return;
+        }
+
+        _completedSteps.Add(1);
+        _currentStep = 2;
+    }
+
+    private void GoBack()
+    {
+        if (_currentStep > 1)
+            _currentStep--;
+    }
+
+    private void GoNext()
+    {
+        _completedSteps.Add(_currentStep);
+        if (_currentStep < 5)
+            _currentStep++;
+    }
+
+    private void GoToStep(int step)
+    {
+        if (_completedSteps.Contains(step) || step == _currentStep)
+            _currentStep = step;
+    }
+
+    private async Task HandleSubmit()
+    {
+        _isSubmitting = true;
+        _submitError = null;
+
+        try
+        {
+            _applicationId = await ApplicationService.SubmitApplicationAsync(_state.ToJobApplication());
+            _submitted = true;
+        }
+        catch (Exception ex)
+        {
+            _submitError = $"Submission failed: {ex.Message}";
+        }
+        finally
+        {
+            _isSubmitting = false;
+        }
+    }
+}
+

toolArgs.file_text:
.step-indicator {
    display: flex;
    justify-content: space-between;
    position: relative;
    padding: 0;
    list-style: none;
    counter-reset: step;
}

.step-indicator::before {
    content: '';
    position: absolute;
    top: 20px;
    left: 10%;
    right: 10%;
    height: 3px;
    background-color: #dee2e6;
    z-index: 0;
}

.step-item {
    display: flex;
    flex-direction: column;
    align-items: center;
    position: relative;
    z-index: 1;
    flex: 1;
}

.step-circle {
    width: 40px;
    height: 40px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 600;
    font-size: 0.9rem;
    border: 3px solid #dee2e6;
    background-color: #fff;
    color: #6c757d;
    transition: all 0.2s;
}

.step-item.active .step-circle {
    border-color: #0d6efd;
    background-color: #0d6efd;
    color: #fff;
}

.step-item.completed .step-circle {
    border-color: #198754;
    background-color: #198754;
    color: #fff;
    cursor: pointer;
}

.step-item.completed .step-circle:hover {
    background-color: #157347;
    border-color: #157347;
}

.step-label {
    margin-top: 8px;
    font-size: 0.8rem;
    color: #6c757d;
    text-align: center;
    max-width: 100px;
}

.step-item.active .step-label {
    color: #0d6efd;
    font-weight: 600;
}

.step-item.completed .step-label {
    color: #198754;
}

