arguments.file_text:
@using sv_2d09572b93304d7c90555106f0b6352d.Models

<div class="step-indicator">
    @for (int i = 0; i < _steps.Length; i++)
    {
        var step = i + 1;
        var label = _steps[i];
        var isActive = step == CurrentStep;
        var isCompleted = CompletedSteps.Contains(step);
        var css = isActive ? "active" : isCompleted ? "completed" : "";

        <div class="step-item @css">
            <div class="step-circle" @onclick="() => HandleClick(step)">
                @if (isCompleted && !isActive)
                {
                    <span>&#10003;</span>
                }
                else
                {
                    @step
                }
            </div>
            <span class="step-label">@label</span>
        </div>
    }
</div>

@code {
    private static readonly string[] _steps =
        ["Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"];

    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter, EditorRequired] public HashSet<int> CompletedSteps { get; set; } = default!;
    [Parameter, EditorRequired] public EventCallback<int> OnStepClicked { get; set; }

    private async Task HandleClick(int step)
    {
        if (CompletedSteps.Contains(step))
            await OnStepClicked.InvokeAsync(step);
    }
}

@using sv_2d09572b93304d7c90555106f0b6352d.Models

<h4 class="mb-3">Personal Information</h4>

<EditForm Model="State" OnValidSubmit="HandleNext" FormName="personalInfo">
    <div class="mb-3">
        <label class="form-label">Full Name <span class="text-danger">*</span></label>
        <InputText class="form-control" @bind-Value="State.FullName" placeholder="Enter your full name" />
        @if (_showValidation && string.IsNullOrWhiteSpace(State.FullName))
        {
            <div class="text-danger small mt-1">Full name is required.</div>
        }
    </div>

    <div class="mb-3">
        <label class="form-label">Email <span class="text-danger">*</span></label>
        <InputText class="form-control" @bind-Value="State.Email" placeholder="you@example.com" type="email" />
        @if (_showValidation && string.IsNullOrWhiteSpace(State.Email))
        {
            <div class="text-danger small mt-1">Email is required.</div>
        }
        @if (!string.IsNullOrEmpty(EmailError))
        {
            <div class="text-danger small mt-1">@EmailError</div>
        }
    </div>

    <div class="mb-3">
        <label class="form-label">Phone <span class="text-danger">*</span></label>
        <InputText class="form-control" @bind-Value="State.Phone" placeholder="(555) 123-4567" />
        @if (_showValidation && string.IsNullOrWhiteSpace(State.Phone))
        {
            <div class="text-danger small mt-1">Phone number is required.</div>
        }
    </div>

    <div class="mb-3">
        <label class="form-label">Address <span class="text-danger">*</span></label>
        <InputTextArea class="form-control" @bind-Value="State.Address" placeholder="Enter your address" rows="2" />
        @if (_showValidation && string.IsNullOrWhiteSpace(State.Address))
        {
            <div class="text-danger small mt-1">Address is required.</div>
        }
    </div>

    <div class="d-flex justify-content-end">
        <button type="submit" class="btn btn-primary" disabled="@_isValidating">
            @if (_isValidating)
            {
                <span class="spinner-border spinner-border-sm me-1"></span>
                <text>Validating...</text>
            }
            else
            {
                <text>Next &rarr;</text>
            }
        </button>
    </div>
</EditForm>

@code {
    [Parameter, EditorRequired] public ApplicationFormState State { get; set; } = default!;
    [Parameter] public string? EmailError { get; set; }
    [Parameter, EditorRequired] public EventCallback OnNext { get; set; }

    private bool _showValidation;
    private bool _isValidating;

    private async Task HandleNext()
    {
        _showValidation = true;

        if (string.IsNullOrWhiteSpace(State.FullName) ||
            string.IsNullOrWhiteSpace(State.Email) ||
            string.IsNullOrWhiteSpace(State.Phone) ||
            string.IsNullOrWhiteSpace(State.Address))
        {
            return;
        }

        _isValidating = true;
        await OnNext.InvokeAsync();
        _isValidating = false;
    }
}

@using sv_2d09572b93304d7c90555106f0b6352d.Models

<h4 class="mb-3">References</h4>

<p class="text-muted">Please provide 2–3 professional references.</p>

@for (int i = 0; i < State.References.Count; i++)
{
    var index = i;
    var reference = State.References[index];

    <div class="card mb-3">
        <div class="card-body">
            <div class="d-flex justify-content-between align-items-center mb-3">
                <h6 class="mb-0">Reference @(index + 1)</h6>
                @if (State.References.Count > 2)
                {
                    <button type="button" class="btn btn-outline-danger btn-sm"
                            @onclick="() => RemoveReference(index)">
                        Remove
                    </button>
                }
            </div>

            <div class="row">
                <div class="col-md-6 mb-3">
                    <label class="form-label">Name</label>
                    <input class="form-control" @bind="reference.Name" placeholder="Reference name" />
                </div>
                <div class="col-md-6 mb-3">
                    <label class="form-label">Relationship</label>
                    <input class="form-control" @bind="reference.Relationship" placeholder="e.g., Former Manager" />
                </div>
            </div>
            <div class="row">
                <div class="col-md-6 mb-3">
                    <label class="form-label">Email</label>
                    <input class="form-control" @bind="reference.Email" placeholder="reference@example.com" type="email" />
                </div>
                <div class="col-md-6 mb-3">
                    <label class="form-label">Phone</label>
                    <input class="form-control" @bind="reference.Phone" placeholder="(555) 123-4567" />
                </div>
            </div>
        </div>
    </div>
}

@if (State.References.Count < 3)
{
    <button type="button" class="btn btn-outline-secondary mb-3" @onclick="AddReference">
        + Add Reference
    </button>
}

<div class="d-flex justify-content-between">
    <button type="button" class="btn btn-secondary" @onclick="OnBack">
        &larr; Back
    </button>
    <button type="button" class="btn btn-primary" @onclick="OnNext">
        Next &rarr;
    </button>
</div>

@code {
    [Parameter, EditorRequired] public ApplicationFormState State { get; set; } = default!;
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }
    [Parameter, EditorRequired] public EventCallback OnNext { get; set; }

    private void AddReference() => State.References.Add(new ReferenceModel());

    private void RemoveReference(int index) => State.References.RemoveAt(index);
}

