+        <button type="submit" class="btn btn-primary" disabled="@_isValidating">
+            @if (_isValidating)
+            {
+                <span class="spinner-border spinner-border-sm me-1"></span>
+                <text>Validating...</text>
+            }
+            else
+            {
+                <text>Next &rarr;</text>
+            }
+        </button>
+    </div>
+</EditForm>
+
+@code {
+    [Parameter, EditorRequired] public ApplicationFormState State { get; set; } = default!;
+    [Parameter] public string? EmailError { get; set; }
+    [Parameter, EditorRequired] public EventCallback OnNext { get; set; }
+
+    private bool _showValidation;
+    private bool _isValidating;
+
+    private async Task HandleNext()
+    {
+        _showValidation = true;
+
+        if (string.IsNullOrWhiteSpace(State.FullName) ||
+            string.IsNullOrWhiteSpace(State.Email) ||
+            string.IsNullOrWhiteSpace(State.Phone) ||
+            string.IsNullOrWhiteSpace(State.Address))
+        {
+            return;
+        }
+
+        _isValidating = true;
+        await OnNext.InvokeAsync();
+        _isValidating = false;
+    }
+}
+

